[self:edit]{path: "note.txt", old_string: "초안", new_string: "완료", replace_all: true}
$위치 = [self:grep]{pattern: "완료", root_path: ".", file_pattern: "note.txt"}
$위치 >> [table:select]{columns: ["파일", "줄번호", "내용"]}

$최신 = [self:file_find]{path: "reports", pattern: "*.md"} >> [table:sort]{by: "mtime", desc: true} >> [table:take]{n: 1}
$본문 = [self:read]{path: "${최신.items.0.path}", start_line: 1, end_line: 220} ?? ($최신 >> [table:each]{do: "[self:read]{path: '${it.path}', start_line: 1, end_line: 220}", keep: ["path"]})
$본문

$본 = [self:read]{path: "input.json"}
$대상 = $본 >> [table:dedup]{by: "url"} >> [table:take]{n: 3}
$결과 = $대상 >> [table:each]{keep: ["title", "url"], on_error: "keep", do: "[try]{[sense:crawl]{url: '$it.url'} >> [table:brief]{instruction: '이 페이지 핵심을 3문장으로 요약. 요약문만 쓴다.'}}[catch]{[table:brief]{items: [$it], instruction: '크롤 실패했다. 요약 대신 다음 오류를 한 줄로 적어라: $error.summary'}}"}
$결과 >> [table:select]{columns: ["title", "url", "message"]} >> [table:rename]{map: {message: "요약"}}

